const COMPARE = [{"title": "NSG と Azure Firewall の比較", "titleEn": "NSG vs Azure Firewall", "cols": ["OSI層", "フィルタリング粒度", "主なユースケース", "高度な機能", "課金モデル"], "colsEn": ["OSI Layer", "Filtering Granularity", "Primary Use Case", "Advanced Features", "Pricing Model"], "rows": [["NSG", "L3/L4", "5タプル(送信元/宛先IP、ポート、プロトコル)", "サブネットやNIC単位のトラフィック許可/拒否", "基本的なルールのみ(FQDNや脅威インテリジェンスは非対応)", "無料(NSGリソース自体は無料)"], ["Azure Firewall", "L3~L7(FQDN、アプリケーション含む)", "5タプル+FQDN+アプリケーションルール", "VNet境界でのセントラル型アウトバウンド/インバウンド制御", "脅威インテリジェンス、TLS検査、IDPS、FQDNフィルタリング", "デプロイ時間+処理データ量で課金"]], "rowsEn": [["NSG", "L3/L4", "5-tuple (source/destination IP, port, protocol)", "Allow/deny traffic per subnet or NIC", "Basic rules only (no FQDN or threat intelligence support)", "Free (the NSG resource itself has no charge)"], ["Azure Firewall", "L3-L7 (incl. FQDN, application)", "5-tuple + FQDN + application rules", "Centralized inbound/outbound control at the VNet boundary", "Threat intelligence, TLS inspection, IDPS, FQDN filtering", "Billed by deployment hours + data processed"]]}, {"title": "プライベートエンドポイント と サービスエンドポイント の比較", "titleEn": "Private Endpoint vs Service Endpoint", "cols": ["接続方式", "IPアドレス", "トラフィック経路", "対応範囲", "主なセキュリティ効果"], "colsEn": ["Connection Method", "IP Address", "Traffic Path", "Scope", "Key Security Benefit"], "rows": [["プライベートエンドポイント", "VNet内にNICとして配置されるPaaS単位の接続", "VNet内のプライベートIP", "Private Link経由でMicrosoftバックボーンのみを通過", "PaaSリソースごとに個別接続", "データ流出防止、オンプレミスからも到達可能"], ["サービスエンドポイント", "サブネットに対してサービスへの最適ルートを有効化", "パブリックIPのまま(サブネットのIDのみ付与)", "最適化されたルートでMicrosoftバックボーンを通過", "サブネット単位でサービスへの経路を最適化", "VNet内からのみアクセス許可(リソース側でVNetルール設定が必要)"]], "rowsEn": [["Private Endpoint", "A per-PaaS-resource connection placed as a NIC inside the VNet", "A private IP inside the VNet", "Traverses only the Microsoft backbone via Private Link", "Connects to individual PaaS resources one at a time", "Prevents data exfiltration; reachable from on-premises too"], ["Service Endpoint", "Enables an optimized route to a service for a subnet", "Keeps the public IP (adds subnet identity only)", "Traverses the Microsoft backbone via an optimized route", "Optimizes the route to a service per subnet", "Allows access only from within the VNet (requires VNet rules on the resource)"]]}, {"title": "Azure RBAC と Key Vault アクセスポリシー の比較", "titleEn": "Azure RBAC vs Key Vault Access Policy", "cols": ["管理単位", "権限の粒度", "監査ログ", "条件付きアクセス/PIM連携", "現在の推奨度"], "colsEn": ["Management Scope", "Permission Granularity", "Audit Logging", "Conditional Access/PIM Integration", "Current Recommendation"], "rows": [["Azure RBAC", "サブスクリプション/リソースグループ/Key Vault単位で割り当て", "keys/secrets/certificates単位で細かく制御可能", "Azure Activity LogとKey Vault診断ログに統合", "条件付きアクセスやPIMと連携可能", "Microsoft推奨(新規は原則こちら)"], ["アクセスポリシー", "Key Vault単位のみ", "オブジェクトタイプ(keys/secrets/certificates)単位の権限設定", "Key Vault診断ログのみ", "連携は限定的", "レガシーモデル、段階的に非推奨"]], "rowsEn": [["Azure RBAC", "Assigned at the subscription, resource group, or vault level", "Fine-grained control per object type (keys/secrets/certificates)", "Integrated into Azure Activity Log and Key Vault diagnostic logs", "Integrates with Conditional Access and PIM", "Recommended by Microsoft (default choice for new vaults)"], ["Access Policy", "Vault level only", "Permissions set per object type (keys/secrets/certificates)", "Key Vault diagnostic logs only", "Limited integration", "Legacy model, being phased out"]]}, {"title": "Defender CSPM と ワークロード保護(CWP) の比較", "titleEn": "Defender CSPM vs Cloud Workload Protection (CWP)", "cols": ["目的", "評価タイミング", "主な機能", "対象範囲", "課金単位"], "colsEn": ["Purpose", "Assessment Timing", "Key Capabilities", "Scope", "Billing Unit"], "rows": [["Defender CSPM", "予防的なリスクベースの態勢管理", "継続的な設定評価(主にエージェントレス)", "攻撃パス分析、セキュアスコア強化、データ対応セキュリティ姿勢、エージェントレススキャン", "マルチクラウド全体のリソース", "リソース単位の課金"], ["ワークロード保護(CWP)", "実行時の脅威検出と対応(検知的)", "エージェントベースまたはクラウドネイティブのリアルタイム監視", "Defender for Servers/SQL/Storage/Containers等の個別プラン", "保護対象のワークロード種別", "ワークロード種別ごとの個別課金"]], "rowsEn": [["Defender CSPM", "Preventive, risk-based posture management", "Continuous configuration assessment (mostly agentless)", "Attack path analysis, security score boost, data-aware security posture, agentless scanning", "Resources across multicloud estates", "Billed per resource"], ["Cloud Workload Protection (CWP)", "Detective runtime threat detection and response", "Agent-based or cloud-native real-time monitoring", "Individual plans such as Defender for Servers/SQL/Storage/Containers", "The specific workload type being protected", "Billed per workload type"]]}, {"title": "Defender for Servers Plan 1 と Plan 2 の比較", "titleEn": "Defender for Servers Plan 1 vs Plan 2", "cols": ["EDR(Defender for Endpoint)統合", "追加のセキュリティ機能", "課金単位", "推奨シナリオ"], "colsEn": ["EDR (Defender for Endpoint) Integration", "Additional Security Features", "Billing Unit", "Recommended Scenario"], "rows": [["Plan 1", "含む(基本統合)", "なし", "サーバーごと(低コスト)", "エンドポイント保護だけで十分な環境"], ["Plan 2", "含む", "脆弱性評価(MDVM)、JIT VMアクセス、ファイル整合性監視(FIM)、適応型アプリケーション制御、自動プロビジョニングなど", "サーバーごと(Plan 1より高コスト)", "フルCSPM/CWP機能が必要なサーバー環境"]], "rowsEn": [["Plan 1", "Included (basic integration)", "None", "Per server (lower cost)", "Environments where endpoint protection alone is sufficient"], ["Plan 2", "Included", "Vulnerability assessment (MDVM), JIT VM access, File Integrity Monitoring (FIM), adaptive application controls, automatic provisioning, and more", "Per server (higher cost than Plan 1)", "Server environments requiring full CSPM/CWP capabilities"]]}, {"title": "マネージドID: システム割当 と ユーザー割当 の比較", "titleEn": "Managed Identity: System-Assigned vs User-Assigned", "cols": ["ライフサイクル", "リソースとの関係", "再利用性", "作成方法", "削除時の挙動"], "colsEn": ["Lifecycle", "Relationship to Resource", "Reusability", "Creation Method", "Behavior on Deletion"], "rows": [["システム割当ID", "関連付けたAzureリソースと同じライフサイクル", "1つのAzureリソースに専属する子オブジェクト", "1つのリソースにのみ紐づく(1対1)", "リソース作成時または有効化時に自動生成", "リソース削除時に自動的に削除される"], ["ユーザー割当ID", "独立したライフサイクル(リソースとは別に管理)", "独立したAzureリソースとして複数のリソースから参照される", "複数のリソースに割り当て可能(1対多)", "独立したAzureリソースとして事前に作成", "リソースが削除されてもIDは残る(明示的な削除が必要)"]], "rowsEn": [["System-Assigned Identity", "Shares the lifecycle of the associated Azure resource", "A child object dedicated to a single Azure resource", "Tied to exactly one resource (1:1)", "Created automatically when the resource is created or the feature is enabled", "Automatically deleted when the resource is deleted"], ["User-Assigned Identity", "Has an independent lifecycle, managed separately from resources", "A standalone Azure resource referenced by multiple resources", "Can be assigned to multiple resources (1:many)", "Created ahead of time as a standalone Azure resource", "Persists after a resource is deleted (must be deleted explicitly)"]]},{"title": "DLP と Purview 内部リスク管理(IRM) の比較", "titleEn": "DLP vs Purview Insider Risk Management (IRM)", "cols": ["目的", "検知対象", "主なポリシーアクション", "データソース", "典型的なユースケース"], "colsEn": ["Purpose", "Detection Target", "Key Policy Actions", "Data Sources", "Typical Use Case"], "rows": [["DLP", "機密データの外部流出防止", "機密情報タイプ・分類子に一致するコンテンツ", "ブロック・警告・暗号化強制", "Exchange/SharePoint/Teams/エンドポイントデバイス", "クレジットカード番号を含むメール送信のブロック"], ["IRM", "内部関係者による意図的/偶発的なリスク行動の検知", "退職予定者のデータ持ち出しなど行動パターン", "アラート生成・調査キューへの追加・自動証拠収集", "Microsoft 365監査ログ・HRシグナル", "退職直前の従業員による大量ファイルダウンロードの検知"]], "rowsEn": [["DLP", "Prevent sensitive data from leaving the organization", "Content matching sensitive information types/classifiers", "Block, warn, or force encryption", "Exchange/SharePoint/Teams/endpoint devices", "Blocking an email containing credit card numbers"], ["IRM", "Detect intentional or accidental risky behavior by insiders", "Behavior patterns such as data exfiltration by a departing employee", "Generate alerts, add to investigation queue, auto-collect forensic evidence", "Microsoft 365 audit logs, HR signals (e.g., resignation)", "Detecting mass file downloads shortly before an employee's last day"]]},{"title": "CMK(顧客管理キー) と PMK(プラットフォーム管理キー) の比較", "titleEn": "Customer-Managed Key (CMK) vs Platform-Managed Key (PMK)", "cols": ["キーの所有者", "保存場所", "ローテーション管理", "失効(取り消し)能力", "主なコンプライアンス用途"], "colsEn": ["Key Owner", "Storage Location", "Rotation Management", "Revocation Capability", "Key Compliance Use"], "rows": [["PMK", "Microsoft", "Microsoft管理のキーストア", "Microsoftが自動管理", "顧客側では制御不可", "標準的な保護要件で追加設定不要"], ["CMK", "顧客", "顧客のAzure Key Vault(顧客サブスクリプション内)", "顧客がポリシーを設定して管理", "顧客がキーを無効化してデータアクセスを遮断できる", "規制要件でCMKが必須な場合、Key Vaultログでの監査証跡が必要な場合"]], "rowsEn": [["PMK", "Microsoft", "A Microsoft-managed key store", "Managed automatically by Microsoft", "Customer cannot revoke it", "Standard protection needs, no extra setup required"], ["CMK", "Customer", "The customer's own Azure Key Vault (in the customer's subscription)", "Managed by the customer via key rotation policy", "Customer can disable the key to cut off data access", "Regulatory requirements mandating customer-held keys; Key Vault log audit trails required"]]},{"title": "Defender for Identity と Defender for Cloud Apps の比較", "titleEn": "Defender for Identity vs Defender for Cloud Apps", "cols": ["保護対象", "データソース", "主な検知シナリオ", "展開方式"], "colsEn": ["Protection Target", "Data Sources", "Key Detection Scenarios", "Deployment Method"], "rows": [["Defender for Identity", "オンプレミスAD DS / Entra IDのID基盤", "ドメインコントローラーのトラフィック・イベントログ", "Pass-the-Hash、DCSync、偵察行動などのID攻撃", "センサーをドメインコントローラーへ配置"], ["Defender for Cloud Apps", "SaaS/クラウドアプリの利用状況", "クラウドアプリのAPIログ、プロキシ/ログコレクタ", "シャドーIT検出、異常なダウンロード、危険なOAuthアプリ", "APIコネクタ/リバースプロキシ経由"]], "rowsEn": [["Defender for Identity", "On-premises AD DS / Entra ID identity fabric", "Domain controller traffic and event logs", "Identity attacks such as Pass-the-Hash, DCSync, reconnaissance", "Sensor deployed on domain controllers"], ["Defender for Cloud Apps", "SaaS/cloud app usage", "Cloud app API logs, proxy/log collector data", "Shadow IT discovery, anomalous downloads, risky OAuth apps", "Via API connectors / reverse proxy"]]},{"title": "Sentinel 分析ルール と 自動化ルール の比較", "titleEn": "Sentinel Analytics Rules vs Automation Rules", "cols": ["目的", "実行タイミング", "主な出力", "典型的な用途"], "colsEn": ["Purpose", "Trigger Timing", "Key Output", "Typical Use"], "rows": [["分析ルール", "ログからインシデントを生成する検知ロジック(KQLベース)", "スケジュール実行またはリアルタイム", "インシデントとアラートの生成", "特定の攻撃パターンを検知してインシデント化する"], ["自動化ルール", "インシデント作成後のトリアージ・割り当て・プレイブック起動を制御する上位ロジック", "インシデントの作成/更新時にトリガー", "タグ付け、担当者割り当て、状態変更、プレイブック起動", "重要度に応じてインシデントを自動的に分類・エスカレーションする"]], "rowsEn": [["Analytics rules", "KQL-based detection logic generating incidents from logs", "Scheduled or near-real-time execution", "Generation of incidents and alerts", "Detecting a specific attack pattern and turning it into an incident"], ["Automation rules", "Higher-level control of triage, assignment, and playbook launch after incident creation", "Triggered on incident creation/update", "Tagging, owner assignment, status change, playbook launch", "Automatically classifying and escalating incidents by severity"]]},{"title": "Azure DDoS Network Protection と IP Protection の比較", "titleEn": "Azure DDoS Network Protection vs IP Protection", "cols": ["適用範囲", "主な機能", "価格モデル", "推奨シナリオ"], "colsEn": ["Scope", "Key Capabilities", "Pricing Model", "Recommended Scenario"], "rows": [["Network Protection", "VNet全体", "専任のDDoS対応チーム(Rapid Response)、コスト保護、攻撃分析レポートを含むフル機能", "VNet単位の月額固定+保護対象IP課金", "ミッションクリティカルな本番環境全体の保護"], ["IP Protection", "個別のパブリックIPアドレス単位", "基本的な緩和機能のみ(Rapid Responseや高度な分析は含まれない)", "保護対象IPアドレスごとの低コスト課金", "特定のワークロードだけを低コストで保護したい場合"]], "rowsEn": [["Network Protection", "An entire VNet", "Full feature set including a dedicated Rapid Response team, cost protection, and attack analytics reports", "A fixed monthly VNet fee plus a charge per protected IP", "Protecting an entire mission-critical production environment"], ["IP Protection", "An individual public IP address", "Baseline mitigation only (no Rapid Response or advanced analytics)", "A low-cost charge per protected IP address", "Protecting only specific workloads at low cost"]]},{"title": "機密ラベル と 保持ラベル の比較", "titleEn": "Sensitivity Labels vs Retention Labels", "cols": ["目的", "主なアクション", "保持/削除への関与", "典型的なユースケース"], "colsEn": ["Purpose", "Key Actions", "Involvement in Retention/Deletion", "Typical Use Case"], "rows": [["機密ラベル", "データの機密度分類と保護", "暗号化の適用、ヘッダー/フッターの追加、共有制限", "保持スケジュールには関与しない", "「極秘」ラベルを付与したファイルを自動暗号化する"], ["保持ラベル", "データのライフサイクル管理(いつまで保持しどう処分するか)", "一定期間後の自動削除、保持義務の適用、記録としての確定", "保持期間や削除ルールを直接制御する", "契約書を7年間保持後に自動削除する"]], "rowsEn": [["Sensitivity labels", "Classify data confidentiality and protect it", "Apply encryption, add headers/footers, restrict sharing", "Not involved in retention scheduling", "Automatically encrypting files labeled \"Highly Confidential\""], ["Retention labels", "Manage the data lifecycle (how long to keep it, how to dispose of it)", "Auto-delete after a period, enforce retention obligations, declare records", "Directly controls retention periods and deletion rules", "Auto-deleting a contract after retaining it for 7 years"]]},{"title": "対称鍵暗号 と 非対称鍵暗号 の比較", "titleEn": "Symmetric vs Asymmetric Encryption", "cols": ["使用する鍵", "処理速度", "主な用途", "代表的なアルゴリズム"], "colsEn": ["Keys Used", "Performance", "Primary Use", "Common Algorithms"], "rows": [["対称鍵暗号", "暗号化と復号に同じ鍵を使用", "高速で大容量データに適する", "保存データ(at rest)の暗号化", "AES"], ["非対称鍵暗号", "公開鍵と秘密鍵のペアを使用", "低速で小さいデータや鍵交換に適する", "鍵交換、デジタル署名、TLSハンドシェイク", "RSA、ECC"]], "rowsEn": [["Symmetric", "Uses the same key for encryption and decryption", "Fast, suited to large volumes of data", "Encrypting data at rest", "AES"], ["Asymmetric", "Uses a public/private key pair", "Slower, suited to small data or key exchange", "Key exchange, digital signatures, TLS handshakes", "RSA, ECC"]]},{"title": "TLS と mTLS(相互TLS) の比較", "titleEn": "TLS vs mTLS (Mutual TLS)", "cols": ["認証方向", "使用する証明書", "典型的な用途", "実装の複雑さ"], "colsEn": ["Authentication Direction", "Certificates Used", "Typical Use", "Implementation Complexity"], "rows": [["TLS", "サーバーのみをクライアントに対して認証", "サーバー証明書のみ", "一般的なWebサイトのHTTPS通信", "比較的シンプル"], ["mTLS", "クライアントとサーバーが相互に認証", "サーバー証明書とクライアント証明書の両方", "サービス間通信、API間のゼロトラスト通信", "証明書配布・管理が必要で複雑"]], "rowsEn": [["TLS", "Only the server is authenticated to the client", "Server certificate only", "Ordinary HTTPS traffic to a website", "Relatively simple"], ["mTLS", "Client and server mutually authenticate each other", "Both server and client certificates", "Service-to-service communication, Zero Trust API traffic", "More complex due to certificate distribution and management"]]},{"title": "プロンプトシールド と コンテンツフィルター の比較", "titleEn": "Prompt Shields vs Content Filters (Microsoft Foundry)", "cols": ["目的", "検知対象", "適用タイミング", "主なリスク軽減"], "colsEn": ["Purpose", "Detection Target", "Applied At", "Primary Risk Mitigated"], "rows": [["プロンプトシールド", "悪意あるプロンプトからモデルを保護する", "直接的なジェイルブレイク試行、文書に埋め込まれた間接的なプロンプトインジェクション", "モデルへの入力時", "モデルの意図しない指示上書きを防止"], ["コンテンツフィルター", "有害なコンテンツの生成・表示を抑制する", "暴力、性的コンテンツ、ヘイト、自傷など有害カテゴリ", "モデルの入力および出力の両方", "不適切な生成AI出力がユーザーに到達することを防止"]], "rowsEn": [["Prompt Shields", "Protect the model from malicious prompts", "Direct jailbreak attempts; indirect prompt injection embedded in documents", "At the point of model input", "Prevents unintended instruction override"], ["Content Filters", "Suppress the generation/display of harmful content", "Harmful categories such as violence, sexual content, hate, self-harm", "Both model input and output", "Prevents inappropriate generative AI output from reaching users"]]},{"title": "Defender for Cloud 無料プラン と Defender CSPM の比較", "titleEn": "Defender for Cloud Free Plan vs Defender CSPM", "cols": ["価格", "攻撃パス分析", "エージェントレススキャン", "Cloud Security Explorer", "マルチクラウド対応"], "colsEn": ["Pricing", "Attack Path Analysis", "Agentless Scanning", "Cloud Security Explorer", "Multicloud Coverage"], "rows": [["Foundational CSPM(無料)", "無料", "利用不可", "利用不可", "利用不可", "Azureのみが対象"], ["Defender CSPM(有料)", "リソース時間課金", "利用可能(グラフベース)", "利用可能(ディスク/コンテナ)", "利用可能", "AWS/GCPも対応"]], "rowsEn": [["Foundational CSPM (Free)", "Free", "Not available", "Not available", "Not available", "Azure only"], ["Defender CSPM (Paid)", "Billed per resource-hour", "Available (graph-based)", "Available (disks/containers)", "Available", "Also covers AWS/GCP"]]},{"title": "Azure RBAC と Microsoft Entra ロール の比較", "titleEn": "Azure RBAC vs Microsoft Entra Roles", "cols": ["管理対象", "スコープの階層", "主なロール例", "割り当て先リソース"], "colsEn": ["What It Manages", "Scope Hierarchy", "Example Roles", "Assignable Resource"], "rows": [["Azure RBAC", "Azureリソースの操作", "管理グループ→サブスクリプション→リソースグループ→リソース", "閲覧者、共同作成者、所有者", "VM、ストレージアカウント等のAzureリソース"], ["Entra ロール", "ディレクトリ(テナント)の操作", "テナント全体(一部は管理単位でスコープ可能)", "グローバル管理者、ユーザー管理者、ヘルプデスク管理者", "ユーザー、グループ、アプリ登録などディレクトリオブジェクト"]], "rowsEn": [["Azure RBAC", "Operations on Azure resources", "Management Group -> Subscription -> Resource Group -> Resource", "Reader, Contributor, Owner", "Azure resources such as VMs and storage accounts"], ["Entra Roles", "Operations on the directory (tenant)", "Whole tenant (some scopable to administrative units)", "Global Administrator, User Administrator, Helpdesk Administrator", "Directory objects such as users, groups, app registrations"]]},{"title": "Defender for Endpoint と Defender for Servers の比較", "titleEn": "Defender for Endpoint vs Defender for Servers", "cols": ["提供形態", "主なライセンス元", "主な機能", "適用対象"], "colsEn": ["Delivery Form", "Primary License Source", "Key Capabilities", "Applies To"], "rows": [["Defender for Endpoint", "独立したEDR製品", "Microsoft 365 E5等", "脅威検知、EDR、脆弱性管理", "主にクライアント端末とサーバー"], ["Defender for Servers", "Defender for Cloudのワークロード保護プラン", "Defender for Cloud(Azure課金)", "EDR自動デプロイ+脆弱性評価+JITアクセス等", "Azure/オンプレ/他クラウドのサーバーのみ"]], "rowsEn": [["Defender for Endpoint", "Standalone EDR product", "Microsoft 365 E5, etc.", "Threat detection, EDR, vulnerability management", "Primarily client devices and servers"], ["Defender for Servers", "A Defender for Cloud workload protection plan", "Defender for Cloud (Azure billing)", "Auto-deploys EDR + vulnerability assessment + JIT access, etc.", "Servers only (Azure, on-premises, multicloud)"]]},{"title": "Sentinel インシデント と アラート の比較", "titleEn": "Sentinel Incident vs Alert", "cols": ["粒度", "生成タイミング", "含まれる情報", "対応の単位"], "colsEn": ["Granularity", "When Generated", "Contained Information", "Unit of Response"], "rows": [["アラート", "個々の検知シグナル", "分析ルールの条件に一致した時", "単一の検知に関する情報のみ", "トリアージの入力"], ["インシデント", "関連する1件以上のアラートの集合", "相関ルールがアラートをグループ化した時", "関連アラート、エンティティ、担当者、ステータス", "調査・クローズのワークフロー単位"]], "rowsEn": [["Alert", "A single detection signal", "When an analytics rule condition is matched", "Information about one detection only", "Input to triage"], ["Incident", "A collection of one or more related alerts", "When correlation groups alerts together", "Related alerts, entities, owner, status", "Unit for investigation and closure workflow"]]},{"title": "パスワードハッシュ同期 と フェデレーション の比較", "titleEn": "Password Hash Sync vs Federation", "cols": ["認証の実行場所", "依存する外部コンポーネント", "オンプレ障害時の影響", "導入の複雑さ"], "colsEn": ["Where Auth Happens", "External Dependency", "Impact of On-Prem Outage", "Deployment Complexity"], "rows": [["パスワードハッシュ同期(PHS)", "Entra ID(クラウド側)", "なし(オンプレIdP不要)", "オンプレADが停止してもクラウド側で認証を継続できる", "低い(Entra Connectの同期設定のみ)"], ["フェデレーション(AD FS)", "オンプレのIdP(AD FS等)", "AD FSサーバーとプロキシが必須", "オンプレIdPが停止すると認証も止まる(フェイルオーバー構成が別途必要)", "高い(サーバー構築・証明書管理・高可用性設計が必要)"]], "rowsEn": [["Password Hash Sync (PHS)", "Entra ID (cloud side)", "None (no on-prem IdP required)", "Cloud-side auth continues even if on-prem AD is down", "Low (only Entra Connect sync configuration)"], ["Federation (AD FS)", "On-premises IdP (e.g., AD FS)", "Requires AD FS servers and a proxy", "Auth stops if the on-prem IdP goes down (needs separate failover design)", "High (requires server build-out, certificate management, HA design)"]]}];

