  const chooseDnd = (itemId, targetId) => setPicks(p => { const cur = { ...(p[pos] || {}) }; if (!targetId) delete cur[itemId]; else cur[itemId] = targetId; const n = { ...p }; if (Object.keys(cur).length === 0) delete n[pos]; else n[pos] = cur; return n; });
  const dndRight = (Q, val) => { const v = val || {}; return (Q.items || []).every(it => v[it.id] === Q.correct[it.id]); };
